import java.io.InputStream
import java.io.PrintWriter
import java.util.HashSet

class FastScanner(private val `in`: InputStream = System.`in`) {
    private val buffer = ByteArray(1 shl 16)
    private var bufferPointer = 0
    private var bytesRead = 0

    private fun fillBuffer() {
        bytesRead = `in`.read(buffer, 0, buffer.size)
        bufferPointer = 0
        if (bytesRead == -1) buffer[0] = -1.toByte()
    }

    private fun read(): Int {
        if (bufferPointer == bytesRead) fillBuffer()
        return buffer[bufferPointer++].toInt()
    }

    fun nextInt(): Int {
        var c = read()
        while (c <= ' ') c = read()
        var neg = false
        if (c == '-') {
            neg = true
            c = read()
        }
        var ret = 0
        while (c >= '0' && c <= '9') {
            ret = ret * 10 + (c - '0')
            c = read()
        }
        return if (neg) -ret else ret
    }

    fun nextIntArray(n: Int): IntArray {
        val arr = IntArray(n)
        for (i in 0 until n) arr[i] = nextInt()
        return arr
    }
}

fun solve(scanner: FastScanner, out: PrintWriter) {
    val n = scanner.nextInt()
    val k = scanner.nextInt()
    val query = scanner.nextIntArray(n)
    var cost = 0
    val availableBooks = HashSet<Int>(k)
    val access = IntArray(81)
    var removable = -1

    for (book in query) access[book]++

    for (i in 0 until n) {
        val currentBook = query[i]
        val doesNotContain = currentBook !in availableBooks
        if (doesNotContain) cost++

        if (removable != -1) {
            availableBooks.remove(removable)
            removable = -1
        } else if (availableBooks.size == k && doesNotContain) {
            var removableBook = -1
            var count = k
            val known = HashSet<Int>()
            for (j in i + 1 until n) {
                if (count == 0) break
                val qj = query[j]
                if (qj in availableBooks && qj !in known) {
                    count--
                    known.add(qj)
                    removableBook = qj
                }
            }
            if (removableBook != -1) {
                availableBooks.remove(removableBook)
            } else {
                availableBooks.remove(availableBooks.iterator().next())
            }
        }
        availableBooks.add(currentBook)
        access[currentBook]--
        if (access[currentBook] == 0) {
            removable = currentBook
        }
    }
    out.println(cost)
}

fun main() {
    val scanner = FastScanner()
    val out = PrintWriter(System.out)
    solve(scanner, out)
    out.flush()
}

